/* @autogenerated */
package net.civeira.phylax.integrationtest.features.oauth.flow;

import java.net.URI;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Map;
import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

import io.quarkus.test.junit.QuarkusTest;
import io.restassured.response.Response;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationResult;
import net.civeira.phylax.integrationtest.features.oauth.fixtures.OidcTestFixtures;
import net.civeira.phylax.integrationtest.features.oauth.scenario.ScenarioDelegateGateway;

@Tag("oidc-flow")
@QuarkusTest
class DelegatedLoginFlowTest extends OidcIntegrationTestBase {

  private static final String PROVIDER = ScenarioDelegateGateway.PROVIDER_ID;

  @Test
  void loginForm_showsDelegatedProviderButton() {
    delegateGateway.setProviderEnabled(true);

    Response response = client.startAuthFlow(OidcTestFixtures.TENANT, OidcTestFixtures.CLIENT_ID,
        OidcTestFixtures.REDIRECT_URI, OidcTestFixtures.SCOPE);

    Assertions.assertEquals(200, response.statusCode());
    String body = response.getBody().asString();
    Assertions.assertTrue(body.contains("social-form-" + PROVIDER),
        "Login form must contain a button for the delegated provider");
    Assertions.assertTrue(body.contains("delegated-login"),
        "Login form must contain the delegated-login step");
  }

  @Test
  void start_redirectsToProvider_withState_andBindingCookie() {
    delegateGateway.setProviderEnabled(true);

    Response start = client.startDelegated(OidcTestFixtures.TENANT, PROVIDER);

    Assertions.assertEquals(302, start.statusCode());
    Assertions.assertTrue(start.getHeader("Location").startsWith("https://accounts.google.com/"));
    Assertions.assertFalse(stateOf(start).isBlank(), "The provider must receive a state");
    Assertions.assertNotNull(start.getCookie("DELEGATED_BINDING"),
        "The browser must receive the binding cookie");
    Assertions.assertTrue(start.getDetailedCookie("DELEGATED_BINDING").isHttpOnly());
  }

  @Test
  void callback_forwardsToAuthorize_escapingProviderValues() {
    delegateGateway.setProviderEnabled(true);
    String state = stateOf(client.startDelegated(OidcTestFixtures.TENANT, PROVIDER));

    Response callback = client.delegatedCallback(PROVIDER,
        Map.of("state", state, "code", "\"><script>alert(1)</script>"));

    Assertions.assertEquals(200, callback.statusCode());
    String body = callback.getBody().asString();
    Assertions.assertTrue(
        body.contains(
            "action=\"/oauth/openid/" + OidcTestFixtures.TENANT + "/authorize?client_id="),
        "The callback must post to the tenant authorize URL");
    Assertions.assertFalse(body.contains("<script>alert(1)</script>"),
        "Provider values must be escaped");
    Assertions.assertEquals("no-store", callback.getHeader("Cache-Control"));
  }

  @Test
  void callback_unknownState_isRejected() {
    delegateGateway.setProviderEnabled(true);

    Response callback = client.delegatedCallback(PROVIDER, Map.of("state", "forged", "code", "x"));

    Assertions.assertEquals(400, callback.statusCode());
  }

  @Test
  void completion_fromSameBrowser_issuesCode() {
    delegateGateway.setProviderEnabled(true);
    delegateGateway.whenResolveUsername(() -> Optional.of(OidcTestFixtures.USERNAME));
    Response start = client.startDelegated(OidcTestFixtures.TENANT, PROVIDER);
    String state = stateOf(start);

    Response response = client.submitQueryDelegated(OidcTestFixtures.TENANT, PROVIDER, state,
        providerData(state, ScenarioDelegateGateway.GOOD_CODE),
        start.getCookie("DELEGATED_BINDING"));

    Assertions.assertEquals(302, response.statusCode());
    Assertions.assertNotNull(client.extractAuthCode(response),
        "Successful delegated login must issue an auth code");
  }

  @Test
  void completion_fromAnotherBrowser_isRefused() {
    delegateGateway.setProviderEnabled(true);
    delegateGateway.whenResolveUsername(() -> Optional.of(OidcTestFixtures.USERNAME));
    refuseFallbackLogin();
    String state = stateOf(client.startDelegated(OidcTestFixtures.TENANT, PROVIDER));

    Response response = client.submitQueryDelegated(OidcTestFixtures.TENANT, PROVIDER, state,
        providerData(state, ScenarioDelegateGateway.GOOD_CODE), "another-browser");

    assertStaysOnLogin(response);
  }

  @Test
  void completion_withoutBindingCookie_isRefused() {
    delegateGateway.setProviderEnabled(true);
    delegateGateway.whenResolveUsername(() -> Optional.of(OidcTestFixtures.USERNAME));
    refuseFallbackLogin();
    String state = stateOf(client.startDelegated(OidcTestFixtures.TENANT, PROVIDER));

    Response response = client.submitQueryDelegated(OidcTestFixtures.TENANT, PROVIDER, state,
        providerData(state, ScenarioDelegateGateway.GOOD_CODE), null);

    assertStaysOnLogin(response);
  }

  @Test
  void completion_isSingleUse() {
    delegateGateway.setProviderEnabled(true);
    delegateGateway.whenResolveUsername(() -> Optional.of(OidcTestFixtures.USERNAME));
    Response start = client.startDelegated(OidcTestFixtures.TENANT, PROVIDER);
    String state = stateOf(start);
    String binding = start.getCookie("DELEGATED_BINDING");
    String data = providerData(state, ScenarioDelegateGateway.GOOD_CODE);
    Assertions.assertEquals(302,
        client.submitQueryDelegated(OidcTestFixtures.TENANT, PROVIDER, state, data, binding)
            .statusCode());
    refuseFallbackLogin();

    Response replay =
        client.submitQueryDelegated(OidcTestFixtures.TENANT, PROVIDER, state, data, binding);

    assertStaysOnLogin(replay);
  }

  @Test
  void completion_rejectedByProvider_staysOnLoginForm() {
    delegateGateway.setProviderEnabled(true);
    delegateGateway.whenResolveUsername(() -> Optional.of(OidcTestFixtures.USERNAME));
    refuseFallbackLogin();
    Response start = client.startDelegated(OidcTestFixtures.TENANT, PROVIDER);
    String state = stateOf(start);

    Response response = client.submitQueryDelegated(OidcTestFixtures.TENANT, PROVIDER, state,
        providerData(state, "forged-code"), start.getCookie("DELEGATED_BINDING"));

    assertStaysOnLogin(response);
  }

  @Test
  void completion_unknownState_staysOnLoginForm() {
    delegateGateway.setProviderEnabled(true);
    refuseFallbackLogin();

    Response response = client.submitQueryDelegated(OidcTestFixtures.TENANT, PROVIDER, "bad-state",
        providerData("bad-state", ScenarioDelegateGateway.GOOD_CODE), "any");

    assertStaysOnLogin(response);
  }

  /**
   * Prevents the fallback password login from accidentally succeeding with empty credentials.
   */
  private void refuseFallbackLogin() {
    loginGateway.whenValidate(() -> AuthenticationResult.wrongCredential(OidcTestFixtures.TENANT,
        OidcTestFixtures.USERNAME));
  }

  private static void assertStaysOnLogin(Response response) {
    Assertions.assertEquals(200, response.statusCode());
    Assertions.assertTrue(response.getBody().asString().contains("name=\"password\""),
        "Login form must be shown when the delegated login is refused");
  }

  private static String providerData(String state, String code) {
    return "{\"state\":[\"" + state + "\"],\"code\":[\"" + code + "\"]}";
  }

  private static String stateOf(Response start) {
    String query = URI.create(start.getHeader("Location")).getRawQuery();
    return Arrays.stream(query.split("&")).filter(p -> p.startsWith("state=")).findFirst()
        .map(p -> URLDecoder.decode(p.substring(6), StandardCharsets.UTF_8)).orElse("");
  }
}
